css-media.style.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
img { max-width: 100%; height: auto; }
a { color: #125a46; }

.walk-card {
  padding: 14px;
  border: 1px solid #b6cfc4;
  border-radius: 8px;
  background: #f5faf7;
}
.walk-card h2 { margin: 0; font-size: 1.125rem; }
.walk-card p { margin: 6px 0 0; }
.walk-legend {
  margin-top: 12px;
  padding: 8px 12px;
  border-left: 3px solid #579176;
  background: #e2f0e8;
}

@media (width < 640px) {
  .walk-legend { display: none; }
}

css-responsive.style.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
img { max-width: 100%; height: auto; }
a { color: #125a46; }

.equipment-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  width: 100%;
}
.equipment-card {
  min-width: 0;
  padding: 12px;
  border: 1px solid #b9cadb;
  border-radius: 8px;
  background: #edf4fc;
}
.equipment-card h2 { margin: 0; font-size: 1.125rem; }
.equipment-card p { margin: 4px 0 0; }

@media (min-width: 680px) {
  .equipment-grid { grid-template-columns: 1fr 1fr; }
}

css-transform.style.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
img { max-width: 100%; height: auto; }
a { color: #125a46; }

.scanner-lane {
  position: relative;
  width: 228px;
  max-width: 100%;
  padding: 8px;
  border-radius: 6px;
  background: #e9f1f8;
}
.scan-target {
  position: absolute;
  top: 8px;
  left: 88px;
  width: 60px;
  height: 38px;
  outline: 2px dashed #6285a5;
  border-radius: 6px;
}
.scanner-head {
  width: 60px;
  height: 38px;
  line-height: 38px;
  text-align: center;
  border-radius: 6px;
  background: #2a5379;
  color: white;
}

.scanner-head { transform: translate(80px, 0); }

css-transition.style.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
