a { color: #125a46; }

.reading-lamp {
  display: inline-block;
  margin-top: 12px;
  padding: 8px 14px;
  border-radius: 8px;
  background: #ffdf91;
  color: #513a13;
  opacity: 0.25;
  transition-property: opacity;
  transition-duration: 0.3s;
  transition-timing-function: ease;
}
.reading-lamp.is-on { opacity: 1; }
